package vn.edu.eaut.lab10.controller;
import java.io.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.edu.eaut.lab10.model.*;import vn.edu.eaut.lab10.repository.UserRepository;
@WebServlet("/admin/users") public class UserController extends HttpServlet{
 private final UserRepository r=new UserRepository();
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String a=q.getParameter("action");if("delete".equals(a)){r.delete(Integer.parseInt(q.getParameter("id")));p.sendRedirect(q.getContextPath()+"/admin/users");return;}if("toggle".equals(a)){User u=r.find(Integer.parseInt(q.getParameter("id")));u.setActive(!u.isActive());r.update(u);p.sendRedirect(q.getContextPath()+"/admin/users");return;}if("edit".equals(a))q.setAttribute("editUser",r.find(Integer.parseInt(q.getParameter("id"))));q.setAttribute("users",r.findAll());q.getRequestDispatcher("/admin/users.jsp").forward(q,p);}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.setCharacterEncoding("UTF-8");String a=q.getParameter("action");try{if("add".equals(a)){if(r.findByEmail(q.getParameter("email"))!=null){q.setAttribute("error","Email đã tồn tại.");}else{User u=new User();u.setEmail(q.getParameter("email"));u.setPassword(q.getParameter("password"));u.setFullName(q.getParameter("fullName"));u.setRole(Role.valueOf(q.getParameter("role")));u.setActive(true);r.save(u);q.setAttribute("success","Thêm thành công.");}}else{User u=r.find(Integer.parseInt(q.getParameter("id")));u.setFullName(q.getParameter("fullName"));u.setRole(Role.valueOf(q.getParameter("role")));if(q.getParameter("password")!=null&&!q.getParameter("password").isBlank())u.setPassword(q.getParameter("password"));r.update(u);q.setAttribute("success","Cập nhật thành công.");}}catch(Exception e){q.setAttribute("error",e.getMessage());}q.setAttribute("users",r.findAll());q.getRequestDispatcher("/admin/users.jsp").forward(q,p);}
}